def longestCommonPrefix(strs):
    for i, ch in enumerate(strs[0]):
        for s in strs[1:]:
            if i >= len(s) or s[i] != ch:
                return strs[0][:i]  # 首个不匹配处截断
    return strs[0]

def reverseWords(s):
    words = s.split()  # 无参切分，自动去掉所有空格
    return ' '.join(words[::-1])  # 逆序后单空格拼接

