def multiply(a, b):
    if a == '0' or b == '0':
        return '0'
    m, n = len(a), len(b)
    res = [0] * (m + n)
    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            res[i + j + 1] += (ord(a[i]) - 48) * (ord(b[j]) - 48)  # 逐位相乘累加
    for k in range(m + n - 1, 0, -1):
        res[k - 1] += res[k] // 10; res[k] %= 10  # 统一进位
    return ''.join(map(str, res)).lstrip('0')  # 去前导零

def compareVersion(v1, v2):
    a, b = v1.split('.'), v2.split('.')
    for i in range(max(len(a), len(b))):
        x = int(a[i]) if i < len(a) else 0  # 空段按 0
        y = int(b[i]) if i < len(b) else 0
        if x != y:
            return 1 if x > y else -1
    return 0
